import { readFile, writeFile } from 'node:fs/promises';

const paths = ['feeds.mjs', 'worker.mjs', 'supabase/functions/gold-scan/scan.mjs'];
const [feeds, worker, scanner] = await Promise.all(paths.map(path => readFile(path, 'utf8')));
const bundle = [
  '// @ts-nocheck',
  '// Generated by build-supabase.mjs.',
  feeds,
  worker.replace('export default {', 'const worker = {'),
  'const apiOnly = true, page = "", css = "", script = "";',
  scanner.replace('export function createGoldScanner', 'function createGoldScanner'),
  `const environment = Deno.env.toObject();
Deno.serve(createGoldScanner({
  environment,
  collect: async () => {
    const response = await worker.fetch(new Request('https://localhost/api/prices'), {
      BTMC_API_KEY: environment.BTMC_API_KEY, readPublishedBtmcKey: true
    });
    return response.json();
  }
}));`
].join('\n');
await writeFile('supabase/functions/gold-scan/index.ts', bundle);
